509  // deriveSearchVerifyCommand walks from the subject's own directory towards the repository root and
510  // stops at the FIRST manifest that licenses a narrow command.
511  //
512  // A manifest that exists but licenses nothing generally does not stop the walk: a `Cargo.toml` that
513  // is only a workspace stanza, or a monorepo leaf `package.json` with no test runner in it, is evidence
514  // about the tree, not about how to run a test, so the walk continues outward to the manifest that is.
515  // Gradle is different once a wrapper and settings establish a project: an ancestor project can
516  // accept the same test pattern without owning that project's sources, so a Gradle project that
517  // declines blocks ancestor Gradle derivation. Other ecosystems still participate farther up the
518  // tree, and a manifest without a runnable Gradle build blocks nothing.
519  func deriveSearchVerifyCommand(subject searchVerifySubject, evidence *searchVerifyEvidence) *SearchVerifyCommand {
520  	dir := path.Dir(subject.sourcePath)
521  	if dir == "." || dir == "/" {
522  		dir = ""
523  	}
524  	gradleBlocked := false
525  	for depth := 0; depth <= searchVerifyMaxDepth; depth++ {
526  		for _, derivation := range searchVerifyDerivations {
527  			if gradleBlocked && derivation.gradle {
528  				continue
529  			}
530  			if command := derivation.run(dir, subject, evidence); command != nil {
531  				return command
532  			}
533  		}
534  		if searchVerifyBlocksAncestorGradle(dir, evidence) {
535  			gradleBlocked = true
536  		}
537  		if dir == "" {
538  			break
539  		}
540  		parent := path.Dir(dir)
541  		if parent == "." || parent == "/" || parent == dir {
542  			dir = ""
543  			continue
544  		}
545  		dir = parent
546  	}
547  	return nil
548  }
