697  func searchVerifyGradleTargetForDir(dir string, evidence *searchVerifyEvidence) (searchVerifyGradleTarget, bool) {
698  	manifest := searchVerifyGradleManifest(dir, evidence)
699  	if manifest == "" {
700  		return searchVerifyGradleTarget{}, false
701  	}
702  	wrapperDir, wrapperPath, ok := searchVerifyAncestorFile(dir, "gradlew", evidence)
703  	if !ok {
704  		return searchVerifyGradleTarget{}, false
705  	}
706  	target := searchVerifyGradleTarget{
707  		wrapperDir:    wrapperDir,
708  		commandPrefix: "./gradlew",
709  		derivedFrom:   manifest + " + " + wrapperPath,
710  	}
711  	if wrapperDir == dir {
712  		return target, true
713  	}
714  	settingsDir, settingsPath, settings, found := searchVerifyGradleAncestorSettings(dir, wrapperDir, evidence)
715  	if !found {
716  		return searchVerifyGradleTarget{}, false
717  	}
718  	target.derivedFrom += " + " + settingsPath
719  	if settingsDir != wrapperDir {
720  		buildRoot, inside := searchVerifyRelative(wrapperDir, settingsDir)
721  		if !inside {
722  			return searchVerifyGradleTarget{}, false
723  		}
724  		target.commandPrefix += " -p " + shellQuotePath(buildRoot)
725  	}
726  	if settingsDir == dir {
727  		target.selectsBuild = true
728  		return target, true
729  	}
730  	projectDir, inside := searchVerifyRelative(settingsDir, dir)
731  	if !inside {
732  		return searchVerifyGradleTarget{}, false
733  	}
734  	project := ":" + strings.ReplaceAll(projectDir, "/", ":")
735  	if !searchVerifyGradleSettingsIncludes(settings, project) {
736  		return searchVerifyGradleTarget{}, false
737  	}
738  	if searchVerifyGradleSettingsRemapsProject(settings, project) {
739  		return searchVerifyGradleTarget{}, false
740  	}

