2021  // deriveSearchVerifyGradle derives a Gradle command. It requires the wrapper — a bare `gradle` may
2022  // not be installed and would not be the repository's own version — and a covering test class,
2023  // because `:module:test` without `--tests` is the whole module and Gradle's project path is only
2024  // worth deriving when it buys a filter.
2025  func deriveSearchVerifyGradle(dir string, subject searchVerifySubject, evidence *searchVerifyEvidence) *SearchVerifyCommand {
2026  	if subject.testPath == "" {
2027  		return nil
2028  	}
2029  	if _, inside := searchVerifyRelative(dir, subject.testPath); !inside {
2030  		return nil
2031  	}
2032  	target, ok := searchVerifyGradleTargetForDir(dir, evidence)
2033  	if !ok {
2034  		return nil
2035  	}
2036  	class := searchVerifyStem(subject.testPath)
2037  	classArg := shellQuote(class)
2038  	if classArg == class {
2039  		// Gradle's established command contract quotes even a shell-safe test pattern. Keep that
2040  		// byte-for-byte form while routing unsafe patterns through the same token encoder.
2041  		classArg = "'" + class + "'"
